parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "message_type": {
      "type": "string",
      "enum": ["alert", "notification"],
      "description": "Use 'alert' if someone might need to act or service is meaningfully broken; use 'notification' for routine info/success updates."
    },
    "title": {
      "type": "string",
      "description": "2–4 words. Human/punchy. No jargon, no IDs, no timestamps. Examples: 'Plex Down', 'Door Unlocked', 'Backup Finished'."
    },
    "severity": {
      "type": "string",
      "enum": ["critical", "warning", "info"],
      "description": "critical = safety/security or urgent outage; warning = degraded/unstable/near limits; info = normal/routine/success."
    },
    "emoji": {
      "type": "string",
      "description": "Exactly one emoji that matches the mood/area (e.g., 📺 for Plex, 🔓 for door unlocked, ✅ for success, ⚠️ for warning)."
    },
    "summary": {
      "type": "string",
      "description": "Family-friendly summary in 1–3 short sentences. Include: what happened + what it means for us + (optional) likely cause in plain English + (optional) what happens next. Keep detail that’s human-meaningful (service/device/room/movie title, counts, percent-full). Do NOT include raw technical identifiers: IPs/ports/URLs with tokens, UUIDs, MACs, container IDs, stack traces, full log lines, exact timestamps, or error codes; translate them to plain language ('connection problem', 'server restarted', 'storage nearly full')."
    },
    "source": {
      "type": "string",
      "description": "Human-friendly name of the system that produced the event (e.g., 'Home Assistant', 'Gatus', 'Plex', 'Sonarr'). No hostnames/URLs."
    }
  },
  "required": ["message_type", "title", "severity", "emoji", "summary", "source"],
  "additionalProperties": false
}

parameters.jsCode:
// Format enriched message as HTML for Telegram
const output = $json.output;

const escapeHtml = (text) => {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
};

// Map severity to a secondary status emoji
const severityMap = {
  'critical': '🔴',
  'warning': '🟡',
  'info': '🔵'
};
const severityIcon = severityMap[output.severity] || '';

// Build the components
const emoji = output.emoji || '🔔';
const title = escapeHtml(output.title || 'Message');
const source = escapeHtml(output.source || 'System');
const summary = escapeHtml(output.summary || '');

// Construct the final message
let message = `${emoji} <b>${title}</b> ${severityIcon}\n\n${summary}`;

// if (source) {
//   message += `\n\n<i>via ${source}</i>`;
// }

// Logic: Notifications are silent, Alerts play sound
let disableNotification = output.message_type === 'notification';

// Override: Always play sound for CRITICAL
if (output.severity === 'critical') {
  disableNotification = false;
}

// Override: Always mute INFO
if (output.severity === 'info') {
  disableNotification = true;
}

return {
  json: {
    message: message,
    disableNotification: disableNotification
  }
};

// Format failed summarizer messages as HTML for Telegram
let output = $json.output;

// 1. Safety check: If output is an object, stringify it so we don't get "[object Object]"
if (typeof output === 'object' && output !== null) {
  output = JSON.stringify(output, null, 2);
}

const escapeHtml = (text) => {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
};

const title = '⚠️ AI Enrichment Failed';
const message = `<b>${title}</b>\n\nCould not process notification. Raw output:\n<pre>${escapeHtml(output)}</pre>`;

// Fallback always plays sound (assume it's important)
return {
  json: {
    message: message,
    disableNotification: false
  }
};

